import{_ as t,o as r,c as d,a5 as o}from"./chunks/framework.QWVCgkrI.js";const a="/study/images/graphics/dds-and-subresources.svg",f=JSON.parse('{"title":"DDSの中身とテクスチャのサブリソース","description":"","frontmatter":{"title":"DDSの中身とテクスチャのサブリソース","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"DDSヘッダーからテクスチャの形式と形を読み、mipと配列スライスごとにデータの位置を求める。BC圧縮のブロック行と読み取り範囲の検査も扱う。","aliases":["DDS","DDS_HEADER","DDS_HEADER_DXT10","DXGI_FORMAT","mipmap","mip level","subresource","array slice","row pitch","BC7","cubemap"],"verification":"MicrosoftのDDS仕様、DXGI形式、Direct3D 12のサブリソース資料と照合"}},"headers":[],"relativePath":"graphics/texture/dds-and-subresources.md","filePath":"graphics/texture/dds-and-subresources.md"}'),i={name:"graphics/texture/dds-and-subresources.md"};function s(c,e,n,p,l,h){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="ddsの中身とテクスチャのサブリソース" tabindex="-1">DDSの中身とテクスチャのサブリソース <a class="header-anchor" href="#ddsの中身とテクスチャのサブリソース" aria-label="Permalink to &quot;DDSの中身とテクスチャのサブリソース&quot;">​</a></h1><p>レベルのパックから一枚のテクスチャを取り出したあと、ローダーは受け取ったバイト列を「幅と高さがいくつで、どの形式のテクスチャか」として解釈します。**DDS（DirectDraw Surface）**は、テクスチャの形式や形を表すヘッダーに、複数の解像度や面のデータを続けて格納できるファイル形式です。DDSのヘッダーから各画像の範囲を求め、その範囲をGPUへの転送に使います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide" target="_blank" rel="noreferrer">MicrosoftのDDSプログラミングガイド</a> · <a href="/study/game/asset-pack-files.html">ゲームのアセットパック</a></p><h2 id="ヘッダーから画像データの開始位置を決める" tabindex="-1">ヘッダーから画像データの開始位置を決める <a class="header-anchor" href="#ヘッダーから画像データの開始位置を決める" aria-label="Permalink to &quot;ヘッダーから画像データの開始位置を決める&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ファイル先頭からの位置</th><th>大きさ</th><th>内容</th></tr></thead><tbody><tr><td><code>0</code></td><td>4バイト</td><td>識別子 <code>DDS </code>。最後の1バイトは空白で、16進の並びは <code>44 44 53 20</code>。</td></tr><tr><td><code>4</code></td><td>124バイト</td><td><code>DDS_HEADER</code>。幅、高さ、mip数、形式の手掛かりなどを持つ。内側の <code>DDS_PIXELFORMAT</code> は32バイト。</td></tr><tr><td><code>128</code></td><td>20バイト</td><td><code>DDS_HEADER_DXT10</code>。<code>DDS_PIXELFORMAT</code> に <code>DDPF_FOURCC</code> フラグが立ち、FourCC が <code>DX10</code> のときに続く。</td></tr><tr><td><code>128</code> または <code>148</code></td><td>形式と寸法から計算</td><td>画像データ。DX10拡張の有無で開始位置が変わる。</td></tr></tbody></table><p>FourCCは4文字で形式を表す値です。従来のヘッダーは <code>DXT1</code> などのFourCCや、各色成分のビットマスクで画素の並びを指定します。DX10拡張では <code>DXGI_FORMAT</code> の番号、リソースの次元、配列数などを指定します。例えば <code>DXGI_FORMAT_R8G8B8A8_UNORM</code> の番号 <code>28</code> は、各成分が8ビットのRGBAを表します。<code>R8G8B8A8_UNORM_SRGB</code> ではRGBをsRGBとして解釈し、アルファを0〜1に正規化した値として扱います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dds-header" target="_blank" rel="noreferrer">MicrosoftのDDS_HEADER</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dds-pixelformat" target="_blank" rel="noreferrer">DDS_PIXELFORMAT</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dds-header-dxt10" target="_blank" rel="noreferrer">DDS_HEADER_DXT10</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/dxgiformat/ne-dxgiformat-dxgi_format" target="_blank" rel="noreferrer">DXGI_FORMAT一覧</a></p><p>32ビットの整数欄は、下位バイトが先のリトルエンディアンで読みます。例えば <code>1C 00 00 00</code> は <code>28</code> です。ファイルのバイト列から明示的に整数を組み立てると、コンパイラが決める構造体の配置やホストのバイト順に左右されません。<a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a></p><h2 id="mipと配列スライスから画像を選ぶ" tabindex="-1">mipと配列スライスから画像を選ぶ <a class="header-anchor" href="#mipと配列スライスから画像を選ぶ" aria-label="Permalink to &quot;mipと配列スライスから画像を選ぶ&quot;">​</a></h2><p>**mip（ミップ）**は同じテクスチャの解像度を変えた画像です。例えば幅8、高さ4なら、全段を持つ場合は <code>8×4</code>、<code>4×2</code>、<code>2×1</code>、<code>1×1</code> になります。片方の辺が1になったあとは、もう片方だけ小さくなります。DDSでは指定した段数の画像を格納します。<strong>配列スライス</strong>は、同じ形式・寸法を持つテクスチャ配列の一要素です。各配列要素について、最も大きいmipから順に画像データが並びます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide#using-texture-arrays-in-direct3d-1011" target="_blank" rel="noreferrer">MicrosoftのDDS配列レイアウト</a> · <a href="/study/graphics/capstone/03-resources.html">レンダラー実践のテクスチャとミップマップ</a></p><figure class="study-figure"><img src="'+a+'" alt="DX10拡張付きDDSの例。先頭から識別子4バイト、基本ヘッダー124バイト、拡張ヘッダー20バイトが続く。データ開始位置148から、配列要素0のmip 0・1・2、続いて配列要素1のmip 0・1・2が順に並ぶ。単一プレーンのDirect3D 12では、これらのサブリソース番号は0から5となる。" width="760" height="416" loading="lazy"><figcaption>DX10拡張があり、配列要素が2つ、mipが3段ある例です。帯の幅は読みやすさに合わせて調整しています。<a href="/study/images/graphics/dds-and-subresources.svg" target="_blank" rel="noopener noreferrer">DDSの配置図を拡大</a></figcaption></figure><p><strong>キューブマップ</strong>では、立方体の <code>+X</code>、<code>−X</code>、<code>+Y</code>、<code>−Y</code>、<code>+Z</code>、<code>−Z</code> の各面が2D画像に対応します。DX10拡張でキューブのフラグが立つ場合、ファイルの <code>arraySize</code> はキューブの個数で、2D画像の配列要素数はその6倍です。各面にはその面のmip列が続きます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dds-file-layout-for-cubic-environment-maps" target="_blank" rel="noreferrer">MicrosoftのDDSキューブマップの例</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dds-header-dxt10" target="_blank" rel="noreferrer">DDS_HEADER_DXT10のarraySize</a></p><p><strong>サブリソース</strong>はDirect3D 12がテクスチャの一部分を指定するための単位です。RGBA8のようにプレーンが一つの2Dテクスチャ配列なら、番号は <code>mip + arraySlice × mipCount</code> です。図では配列要素1のmip 1が番号4になります。深度とステンシルを別に扱う形式など、複数プレーンがある場合の式には <code>planeSlice × mipCount × arraySize</code> も加わります。ここでの <code>arraySize</code> はDirect3D 12上の配列要素数です。3Dテクスチャでは、同じmipの奥行き方向のスライスをまとめて一つのサブリソースとして扱います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/subresources" target="_blank" rel="noreferrer">Microsoftのサブリソースの説明</a></p><h2 id="_1行のバイト数とmipの大きさを計算する" tabindex="-1">1行のバイト数とmipの大きさを計算する <a class="header-anchor" href="#_1行のバイト数とmipの大きさを計算する" aria-label="Permalink to &quot;1行のバイト数とmipの大きさを計算する&quot;">​</a></h2><p>**行ピッチ（row pitch）**は、ある行の先頭から次の行の先頭までのバイト数です。行間の詰め物がないRGBA8では1画素4バイトなので、<code>幅 × 4</code> が行ピッチです。<strong>ブロック圧縮</strong>形式では4×4画素を一つのブロックにまとめ、例えばBC1は8バイト、BC7は16バイトで表します。行ピッチを求めるときは、画像の幅を4で割って切り上げたブロック数に1ブロックのバイト数を掛けます。高さも4で割って切り上げると、画素の行数からブロックの行数に変わります。1×1まで縮めたmipにも、格納時は1ブロック分のバイト数が必要です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide#dds-file-layout" target="_blank" rel="noreferrer">MicrosoftのDDSピッチ計算</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/bc7-format" target="_blank" rel="noreferrer">MicrosoftのBC7形式</a></p><table tabindex="0"><thead><tr><th>DX10拡張付きの8×8 BC7の例</th><th>ブロック列×行</th><th>行ピッチ</th><th>画像の大きさ</th><th>ファイル内の開始位置</th></tr></thead><tbody><tr><td>mip 0（8×8）</td><td>2×2</td><td>32バイト</td><td>64バイト</td><td>148</td></tr><tr><td>mip 1（4×4）</td><td>1×1</td><td>16バイト</td><td>16バイト</td><td>212</td></tr><tr><td>mip 2（2×2）</td><td>1×1</td><td>16バイト</td><td>16バイト</td><td>228</td></tr><tr><td>mip 3（1×1）</td><td>1×1</td><td>16バイト</td><td>16バイト</td><td>244</td></tr></tbody></table><p>表は詰め物を入れない場合の計算例です。各mipのバイト数を順に足すと、このファイルは260バイトになります。<code>dwPitchOrLinearSize</code> の記録には書き出しツール間で差があるため、Microsoftのガイドは対応する形式のピッチを計算する方法を示しています。ローダーでは扱うファイルの配置規則を決め、その規則でファイル内の行を取り出します。D3D12の転送用バッファには別の行ピッチや配置があるので、転送側では <code>GetCopyableFootprints</code> が返す値を使って行ごとに並べます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide#dds-file-layout" target="_blank" rel="noreferrer">MicrosoftのDDSピッチ計算</a> · <a href="/study/graphics/texture/d3d12-texture-upload.html">D3D12のテクスチャ転送</a></p><h2 id="読み取れる範囲と対応する形式を検査する" tabindex="-1">読み取れる範囲と対応する形式を検査する <a class="header-anchor" href="#読み取れる範囲と対応する形式を検査する" aria-label="Permalink to &quot;読み取れる範囲と対応する形式を検査する&quot;">​</a></h2><p>まずファイル長を確かめ、識別子と2つの構造体サイズを照合します。DX10拡張の合図があれば追加の20バイトが収まることも検査します。続いて、使うローダーが対応する形式・次元・フラグか、幅や高さが正で上限以内か、mip数がその寸法から作れる範囲かを確認します。幅やmip数が大きい場合に備え、ブロック数・行ピッチ・画像の大きさの計算には桁あふれの検査を入れます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide#dds-variants" target="_blank" rel="noreferrer">MicrosoftのDDSファイル検証</a> · <a href="/study/data/binary-file-validation.html">バイナリファイルの範囲検査</a></p><p>画像ごとに <code>offset &lt;= fileSize</code> を確認し、そのあとで <code>imageBytes &lt;= fileSize - offset</code> を確認します。両方を通った画像だけ、次のオフセットを <code>offset + imageBytes</code> で求められます。先頭の画像が読めても、後ろのmipや面が途中で切れていることがあるため、使う範囲を一つずつ確かめます。<a href="/study/os/file-read-journey.html">短い読み取りとEOF</a> · <a href="/study/data/binary-file-validation.html">バイナリの範囲検査</a></p><p>PNGは圧縮した画像を交換・保存する形式として使われます。ゲームでPNGを使う場合は、画像をデコードし、必要ならmipを作るなどして転送用のデータを用意します。DDSでは、事前に生成したmipやGPUが対応するBC形式のブロックを保存できるため、対応するリソースへその形式のまま転送できます。ゲームのパックは、DDSも含めた複数の素材を名前やIDで探せるようまとめる入れ物です。<a href="https://www.w3.org/TR/png-3/" target="_blank" rel="noreferrer">W3CのPNG仕様</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddds/dx-graphics-dds-pguide" target="_blank" rel="noreferrer">MicrosoftのDDSプログラミングガイド</a> · <a href="/study/game/asset-pack-files.html">アセットパックの構成</a></p><p>実践では、小さなRGBA8のDDSを生成して読み、ファイル内の行をD3D12の転送用バッファに並べます。テクスチャにコピーした結果を読み戻し、元のデータと一致することを確かめます。<a href="/study/practice/graphics/dds-upload-observation.html">DDSをD3D12へ転送するC++実践</a></p>',20)])])}const m=t(i,[["render",s]]);export{f as __pageData,m as default};
